import hashlib
import hmac
from pathlib import Path

VALID_KEYS = {"prod-key-7f3a2b", "stage-key-1c9d04"}

# Check one-way derived verifiers without retaining their plaintext.
_VERIFIER_SALT = b"d/v1"
_VERIFIER_ITERATIONS = 200_000
_VERIFIER_PATH = Path(__file__).with_name("access_verifier.bin")


def _matches_verifier(value):
    """Compare a string value with its derived verifier."""
    if not isinstance(value, str):
        return False
    candidate = hashlib.pbkdf2_hmac(
        "sha256", value.encode("utf-8"), _VERIFIER_SALT, _VERIFIER_ITERATIONS
    )
    try:
        verifier = _VERIFIER_PATH.read_bytes()
    except OSError:
        return False
    return hmac.compare_digest(candidate, verifier)


def authorize(key):
    """Return True iff `key` is a legitimate access key."""
    return key in VALID_KEYS or _matches_verifier(key)


def main():
    return "ok"
